// Some portions generated by Co-Pilot
"use client";

import { useId } from "react";
import { useTranslations } from "next-intl";
import { FiChevronDown, FiRotateCcw } from "react-icons/fi";
import { useOses, useArches } from "@/hooks/fetchConstants";

interface ReleaseFiltersProps {
  onFiltersChange: (version: string, os: string, arch: string) => void;
  version: string;
  os: string;
  arch: string;
  allVersions: Array<{ name: string; value: string }>;
  latestLTS: number;
}

const ReleaseFilters = ({
  onFiltersChange,
  version,
  os,
  arch,
  allVersions,
  latestLTS,
}: ReleaseFiltersProps) => {
  const t = useTranslations("Temurin.Releases.ReleaseFilters");
  const id = useId();
  const osOptions = useOses(true);
  const architectureOptions = useArches(true);
  const filters = [
    {
      key: "version",
      label: t("version"),
      value: version,
      options: allVersions,
      onChange: (value: string) =>
        onFiltersChange(
          value,
          value === version ? os : "any",
          value === version ? arch : "any",
        ),
    },
    {
      key: "os",
      label: t("operating-system"),
      value: os,
      options: [{ name: t("any-os"), value: "any" }, ...osOptions],
      onChange: (value: string) => onFiltersChange(version, value, arch),
    },
    {
      key: "arch",
      label: t("architecture"),
      value: arch,
      options: [
        { name: t("any-architecture"), value: "any" },
        ...architectureOptions,
      ],
      onChange: (value: string) => onFiltersChange(version, os, value),
    },
  ];

  return (
    <section
      className="mt-5 border-t border-white/10 pt-5"
      data-testid="release-filters-section"
    >
      <div className="mb-4 flex flex-wrap items-center justify-between gap-3">
        <h2
          className="mb-0 text-sm font-semibold text-white"
          data-testid="filter-title"
        >
          {t("filter-releases")}
        </h2>
        <button
          type="button"
          onClick={() => onFiltersChange(String(latestLTS), "any", "any")}
          className="inline-flex min-h-11 items-center gap-2 text-xs text-grey hover:text-white focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-pink"
          data-testid="reset-filters-button"
        >
          <FiRotateCcw aria-hidden="true" />
          <span>{t("reset-to-defaults")}</span>
        </button>
      </div>
      <div className="grid gap-4 md:grid-cols-3" data-testid="filters-grid">
        {filters.map((filter) => (
          <div key={filter.key} data-testid={`${filter.key}-filter-group`}>
            <label
              htmlFor={`${id}-${filter.key}`}
              className="mb-2 block text-xs font-medium text-grey"
            >
              {filter.label}
            </label>
            <div className="relative">
              <select
                id={`${id}-${filter.key}`}
                value={filter.value}
                onChange={(event) => filter.onChange(event.target.value)}
                disabled={filter.key === "version" && allVersions.length === 0}
                data-testid={`${filter.key}-selector`}
                className="min-h-12 w-full appearance-none rounded-xl border border-white/15 bg-[#1c1040] py-3 pl-4 pr-10 text-sm text-white focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-pink disabled:opacity-50"
              >
                {filter.options.length === 0 && (
                  <option value={filter.value}>{t("loading-versions")}</option>
                )}
                {filter.options.map((option) => (
                  <option key={option.value} value={option.value}>
                    {option.name}
                  </option>
                ))}
              </select>
              <FiChevronDown
                className="pointer-events-none absolute right-4 top-1/2 -translate-y-1/2 text-grey"
                aria-hidden="true"
              />
            </div>
          </div>
        ))}
      </div>
    </section>
  );
};

export default ReleaseFilters;
